// QueryServer is the server API for Query service.
type QueryServer interface {
	// Parameters queries the parameters of the module.
	Params(context.Context, *QueryParamsRequest) (*QueryParamsResponse, error)
	// ListPolicyPermissions Queries a list of PolicyPermissions items.
	GetPolicyPermissions(context.Context, *QueryGetPolicyPermissionsRequest) (*QueryGetPolicyPermissionsResponse, error)
	// ListPolicyPermissions defines the ListPolicyPermissions RPC.
	ListPolicyPermissions(context.Context, *QueryAllPolicyPermissionsRequest) (*QueryAllPolicyPermissionsResponse, error)
	// GetDecisionPolicy returns the DecisionPolicy (voting threshold, voting
	// period, min execution period) for a given council policy address. Read-only.
	GetDecisionPolicy(context.Context, *QueryGetDecisionPolicyRequest) (*QueryGetDecisionPolicyResponse, error)
	// ListDecisionPolicies returns every stored DecisionPolicy paginated, paired
	// with its policy_address. Useful for UIs that want to render every council's
	// voting rules in one pass.
	ListDecisionPolicies(context.Context, *QueryAllDecisionPoliciesRequest) (*QueryAllDecisionPoliciesResponse, error)
	// GetGroup queries a specific group by name.
	GetGroup(context.Context, *QueryGetGroupRequest) (*QueryGetGroupResponse, error)
	// ListGroups queries all groups.
	ListGroups(context.Context, *QueryAllGroupRequest) (*QueryAllGroupResponse, error)
	// GetCouncilMembers queries the members of a specific council.
	GetCouncilMembers(context.Context, *QueryGetCouncilMembersRequest) (*QueryGetCouncilMembersResponse, error)
	// GetProposal queries a specific proposal by ID.
	GetProposal(context.Context, *QueryGetProposalRequest) (*QueryGetProposalResponse, error)
	// ListProposals queries all proposals with optional filtering.
	ListProposals(context.Context, *QueryListProposalsRequest) (*QueryListProposalsResponse, error)
	// GetProposalVotes queries votes for a specific proposal.
	GetProposalVotes(context.Context, *QueryGetProposalVotesRequest) (*QueryGetProposalVotesResponse, error)
	// GetCategory queries a single shared content category by id.
	GetCategory(context.Context, *QueryGetCategoryRequest) (*QueryGetCategoryResponse, error)
	// ListCategory queries all shared content categories.
	ListCategory(context.Context, *QueryAllCategoryRequest) (*QueryAllCategoryResponse, error)
	// GetRecurringSpend queries a single recurring spend schedule by id.
	GetRecurringSpend(context.Context, *QueryGetRecurringSpendRequest) (*QueryGetRecurringSpendResponse, error)
	// ListRecurringSpends queries recurring spend schedules, optionally
	// filtered by authority (council policy address) or recipient.
	ListRecurringSpends(context.Context, *QueryListRecurringSpendsRequest) (*QueryListRecurringSpendsResponse, error)
	// GetPoll returns a poll.
	GetPoll(context.Context, *QueryGetPollRequest) (*QueryGetPollResponse, error)
	// ListPolls lists stored polls in ID order (pagination.reverse for newest
	// first), optionally for one group and one status.
	ListPolls(context.Context, *QueryListPollsRequest) (*QueryListPollsResponse, error)
	// GetPollVotes lists the open votes on a poll.
	GetPollVotes(context.Context, *QueryGetPollVotesRequest) (*QueryGetPollVotesResponse, error)
	// GetProposalVoterTree returns a secret-ballot proposal's voter snapshot
	// (while voting is open), for building a shield proof.
	GetProposalVoterTree(context.Context, *QueryGetProposalVoterTreeRequest) (*QueryGetProposalVoterTreeResponse, error)
	// GetPollVoterTree returns a secret-ballot poll's voter snapshot (while
	// voting is open).
	GetPollVoterTree(context.Context, *QueryGetPollVoterTreeRequest) (*QueryGetPollVoterTreeResponse, error)
	// TreasuryStake reports how much SPARK the group treasuries have staked
	// together and how much more the treasury stake cap lets them delegate.
	TreasuryStake(context.Context, *QueryTreasuryStakeRequest) (*QueryTreasuryStakeResponse, error)
}

